-- Al final, un DO comprueba 133 principales, 71 agrupados y 127 códigos; si no cuadra, aborta.
DO $$
DECLARE
    principals INT;
    keyed      INT;
    grouped    INT;
    codes      INT;
BEGIN
    SELECT count(*) FILTER (WHERE is_campus AND parent_building_id IS NULL), count(plan_key), count(parent_building_id)
      INTO principals, keyed, grouped
      FROM campus_buildings WHERE deleted_at IS NULL;
    SELECT count(*) INTO codes FROM campus_building_codes WHERE deleted_at IS NULL;
    IF principals <> 133 OR keyed <> 133 OR grouped <> 71 OR codes <> 127 THEN
        RAISE EXCEPTION 'SPEC-108: se esperaban 133 principales, 71 agrupados y 127 códigos; hay % (% con plan_key), % y %',
            principals, keyed, grouped, codes;
    END IF;
END $$;
